#!/usr/bin/env python3
"""
Passo 7 v2 - File manager proprio para "Mover para album" (Player3D / Galeria3D).

Substitui o fluxo do Passo 7 v1 (mover direto pela grade de Albuns do
MediaStore) por um file manager PROPRIO do app, com a cara da grade 3D:
  - Ao selecionar faixas e tocar "Mover para album", o app abre uma
    grade 3D mostrando as pastas do sdcard (sem capa -- so um icone de
    pasta), navegavel livremente a partir da raiz do armazenamento.
  - Permite criar pastas novas ali dentro (dialogo simples pedindo nome).
  - Ao confirmar "OK", a pasta atual vira o destino e as faixas
    selecionadas sao movidas fisicamente para la.
  - Pede a permissao "Acesso a todos os arquivos" (MANAGE_EXTERNAL_STORAGE)
    quando necessario, levando direto a tela nativa do Android para
    conceder.
  - O antigo "Criar album" do menu overflow foi removido (nao fazia mais
    sentido -- criar pasta agora acontece dentro do proprio file manager).

Rode este script de dentro de ~/Galeria3D (raiz do repo clonado).
Idempotente: pode rodar 2x sem quebrar nada.
Cada arquivo tocado ganha um .bak antes de ser sobrescrito.
"""

import base64
import io
import os
import shutil
import sys
import tarfile

FILES = {
    "app/src/main/java/com/android/gallery3d/app/FilePickerPage.java": "FilePickerPage.java",
    "app/src/main/java/com/android/gallery3d/ui/FilePickerSlotRenderer.java": "FilePickerSlotRenderer.java",
    "app/src/main/res/menu/filepicker.xml": "filepicker.xml",
    "app/src/main/AndroidManifest.xml": "AndroidManifest.xml",
    "app/src/main/java/com/android/gallery3d/app/AlbumPage.java": "AlbumPage.java",
    "app/src/main/java/com/android/gallery3d/app/AlbumSetPage.java": "AlbumSetPage.java",
    "app/src/main/res/menu/albumset.xml": "albumset.xml",
    "app/src/main/res/values/strings.xml": "strings.xml",
    "app/src/main/res/values-pt/strings.xml": "strings-pt.xml",
}

PAYLOAD_B64 = ""


def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    return tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")


def already_applied():
    path = "app/src/main/java/com/android/gallery3d/app/FilePickerPage.java"
    return os.path.isfile(path)


def main():
    if not os.path.isdir("app/src/main/java/com/android/gallery3d"):
        print("ERRO: nao encontrei app/src/main/java/com/android/gallery3d")
        print("Rode este script de dentro da pasta raiz do repo (~/Galeria3D).")
        sys.exit(1)

    if already_applied():
        print("Passo 7 v2 ja aplicado anteriormente (FilePickerPage.java ja")
        print("existe) — nada a fazer (script e idempotente).")
        sys.exit(0)

    tar = load_payload()
    members = {m.name.lstrip("./"): m for m in tar.getmembers()}

    for repo_path, payload_name in FILES.items():
        if payload_name not in members:
            print(f"ERRO interno: payload nao contem {payload_name}")
            sys.exit(1)

    backups = []
    try:
        for repo_path, payload_name in FILES.items():
            new_content = tar.extractfile(members[payload_name]).read()

            if os.path.isfile(repo_path):
                backup_path = repo_path + ".bak"
                shutil.copyfile(repo_path, backup_path)
                backups.append(backup_path)
                print(f"Backup criado: {backup_path}")
            else:
                os.makedirs(os.path.dirname(repo_path), exist_ok=True)

            with open(repo_path, "wb") as f:
                f.write(new_content)
            print(f"Atualizado: {repo_path}")

    except Exception as e:
        print(f"ERRO durante a aplicacao: {e}")
        print("Arquivos ja copiados tem backup .bak ao lado, revise manualmente se necessario.")
        sys.exit(1)

    print()
    print("Passo 7 v2 aplicado com sucesso.")
    print()
    print("O que foi feito:")
    print("- Selecione faixas (toque longo) em qualquer filtro e toque no")
    print("  icone de 'Mover para album' no menu de selecao.")
    print("- Na primeira vez, um popup vai pedir a permissao 'Acesso a")
    print("  todos os arquivos' e abrir a tela do sistema para conceder.")
    print("  IMPORTANTE: depois de conceder, toque em 'Mover para album'")
    print("  de novo -- o fluxo nao retoma sozinho.")
    print("- O file manager proprio abre por cima da grade, mostrando as")
    print("  pastas do sdcard (com icone de pasta, sem capa). Navegue,")
    print("  crie pastas novas se quiser (icone de + na barra), e toque")
    print("  no icone de confirmar (disquete) para mover as faixas para")
    print("  a pasta que voce esta navegando no momento.")
    print("- O antigo 'Criar album' do menu overflow foi removido -- criar")
    print("  pasta agora acontece dentro do file manager.")
    print()
    print("Proximo passo: recompile o app e teste o fluxo completo,")
    print("incluindo a concessao da permissao de acesso a arquivos.")


if __name__ == "__main__":
    main()
